prompt:
Create unit `tasks` and implement `is_sorted`: true exactly when every element is <= the next one. The contract must state that equivalence.

Required signature (in unit `tasks`):
fn is_sorted(a: &[i64]) -> (r: bool)

reference.code:
spec fn sorted_below(a: &[i64], n: usize) -> bool { forall|k: usize| k + 1 < n ==> #[trigger] a[k] <= a[k + 1] }

spec fn sorted_spec(a: &[i64], r: bool) -> bool { r == (forall|k: usize| k + 1 < a.len() ==> #[trigger] a[k] <= a[k + 1]) }

#[effects(pure)]
#[uses(sorted_below, sorted_spec)]
fn is_sorted(a: &[i64]) -> (r: bool)
    ensures sorted_spec(a, r),
{
    let mut k: usize = 1;
    while k < a.len() && a[k - 1] <= a[k]
        invariant 1 <= k, k <= a.len() || a.len() == 0, sorted_below(a, k),
        decreases a.len() - k,
    {
        k = k + 1;
    }
    k >= a.len()
}
